/**
* Used to request an access token.
*/
function createGcpServiceAccountJwt(clientEmail, privateKey, scopes, expiresInS = 30) {
	return signJwt("RS256", privateKey, {
		expiresInS,
		issuer: clientEmail,
		audience: "https://oauth2.googleapis.com/token",
		scope: scopes.join(" ")
	});
}
