//#region src/stores/chrome-web-store-v2.ts
var ChromeWebStoreV2 = class {
	options;
	setStatus;
	client;
	accessTokenCache;
	constructor(options, setStatus) {
		this.options = options;
		this.setStatus = setStatus;
		this.client = createHttpClient({
			baseUrl: BASE_URL,
			defaultHeaders: async () => ({
				Authorization: `Bearer ${await this.getAccessToken()}`,
				"x-goog-api-version": "2"
			})
		});
	}
	async submit(dryRun) {
		this.setStatus?.("Validating credentials");
		const status = await this.client.get("/v2/{+name}:fetchStatus", { params: { name: this.nameParam } });
		if (dryRun) {
			this.setStatus?.("DRY RUN: Skipped upload and publishing");
			return;
		}
		if (this.options.cancelPending && status.submittedItemRevisionStatus?.state === "PENDING_REVIEW") {
			this.setStatus?.("Cancelling pending review");
			await this.client.post("/v2/{+name}:cancelSubmission", {
				params: { name: this.nameParam },
				body: {}
			});
		}
		this.setStatus?.("Uploading new ZIP file");
		const file = createReadStream(this.options.zip);
		const uploadRes = await this.client.post("/upload/v2/{+name}:upload", {
			params: { name: this.nameParam },
			body: file
		});
		this.checkUploadState(uploadRes);
		if (this.options.skipSubmitReview) {
			this.setStatus?.("Skipping submission (skipSubmitReview=true)");
			return;
		}
		this.setStatus?.("Submitting for review");
		const publishRes = await this.client.post("/v2/{+name}:publish", {
			params: { name: this.nameParam },
			body: {
				blockOnWarnings: void 0,
				deployInfos: this.options.deployPercentage ? [{ deployPercentage: this.options.deployPercentage }] : void 0,
				publishType: this.options.publishType,
				skipReview: this.options.skipReview
			}
		});
		if (publishRes.warningInfo?.warnings?.length) {
			this.setStatus?.(`Found ${publishRes.warningInfo.warnings.length} warning(s)`);
			for (const warning of publishRes.warningInfo.warnings) logger.warn(`${warning.reason}: ${warning.description}`);
		}
	}
	async ensureZipsExist() {
		await ensureZipExists(this.options.zip);
	}
	/**
	* @param percentage A nonnegative number between 0 and 100.
	*/
	async setDeploymentPercentage(percentage) {
		await this.client.post("/v2/{+name}:setPublishedDeployPercentage", {
			params: { name: this.nameParam },
			body: { deployPercentage: percentage }
		});
	}
	async getStatus() {
		return await this.client.get("/v2/{+name}:fetchStatus", { params: { name: this.nameParam } });
	}
	async getAccessToken() {
		if (!this.accessTokenCache) this.accessTokenCache = this.getAccessTokenNoCache();
		return (await this.accessTokenCache).access_token;
	}
	async getAccessTokenNoCache() {
		const res = await fetch("https://oauth2.googleapis.com/token", {
			method: "POST",
			headers: { "Content-Type": "application/x-www-form-urlencoded" },
			body: new URLSearchParams({
				grant_type: "urn:ietf:params:oauth:grant-type:jwt-bearer",
				assertion: createGcpServiceAccountJwt(this.options.serviceAccountClientEmail, this.options.serviceAccountPrivateKey, ["https://www.googleapis.com/auth/chromewebstore"])
			})
		});
		if (!res.ok) throw new Error(`Failed to exchange service account credentials for access token: ${res.status} ${res.statusText}`);
		return await res.json();
	}
	get nameParam() {
		return `publishers/${this.options.publisherId}/items/${this.options.extensionId}`;
	}
	checkUploadState(item) {
		if (item.uploadState !== "SUCCEEDED") throw new ChromeWebStoreUploadStateError(item);
	}
};
