const escapeChars = [
	"=",
	"\n",
	"$",
	"#",
	" ",
	"\"",
	"'"
];
function setDotenvValue(dotenv, key, value) {
	const wrappedValue = escapeChars.some((char) => value.includes(char)) ? `"${value.replaceAll("\"", "\\\"")}"` : value;
	const keyIndex = findKey(dotenv, key);
	return keyIndex == null ? appendKey(dotenv, key, wrappedValue) : replaceKey(dotenv, key, wrappedValue, keyIndex);
}
function findKey(dotenv, key) {
	const match = new RegExp(`(^|\n)\\s*${RegExp.escape(key)}=`, "m").exec(dotenv);
	if (match) return dotenv.indexOf(key, match.index);
}
function appendKey(dotenv, key, value) {
	const insert = `${key}=${value}`;
	if (dotenv[dotenv.length - 1] === "\n") return `${dotenv}${insert}\n`;
	if (dotenv.length === 0) return insert;
	return dotenv + `\n${insert}`;
}
function replaceKey(dotenv, key, wrappedValue, keyIndex) {
	const start = keyIndex + key.length + 1;
	const hasQuotes = dotenv[start] === "\"" || dotenv[start] === "'";
	let end;
	if (hasQuotes) {
		const quote = dotenv[start];
		end = start + 1;
		while (end < dotenv.length && dotenv[end] !== quote && dotenv[end - 1] !== "\\") end++;
		end++;
	} else {
		end = dotenv.indexOf("\n", start);
		if (end == -1) end = dotenv.length;
	}
	return dotenv.substring(0, start) + wrappedValue + dotenv.substring(end);
}
